output_text:
[
  {
    "id": "must_take_entrance_cart",
    "text": "The shopper is obliged to take the entrance cart before completing the trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_rack": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "cart_in_use": "hasCart"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_rack",
              "PICKUP_CART"
            ]
          },
          "post": "cart_in_use"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "must_return_cart_bay",
    "text": "The shopper is obliged to return the cart to the front-left cart bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "front_cart_bay": "at(0,1)",
        "cart_parked_in_bay": "cartAt(0,1)",
        "cart_in_use": "hasCart"
      },
      "events": {
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "front_cart_bay",
              "cart_in_use",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "no_exit_before_cart_returned",
    "text": "The shopper is prohibited from exiting unless the cart has already been parked in the front-left cart bay.",
    "abstraction": {
      "state_properties": {
        "cart_parked_in_bay": "cartAt(0,1)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "cart_parked_in_bay"
          }
        ]
      }
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "The shopper is prohibited from leaving the supermarket while still pushing or holding a cart.",
    "abstraction": {
      "state_properties": {
        "cart_in_use": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          "cart_in_use"
        ]
      }
    }
  },
  {
    "id": "leave_cart_only_at_bay",
    "text": "The shopper is prohibited from putting the cart down anywhere except the designated cart bay at (0,1).",
    "abstraction": {
      "state_properties": {
        "front_cart_bay": "at(0,1)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "LEAVE_CART",
          {
            "not": "front_cart_bay"
          }
        ]
      }
    }
  },
  {
    "id": "pickup_items_only_with_cart",
    "text": "The shopper is prohibited from picking up shelf items unless they currently have the cart.",
    "abstraction": {
      "state_properties": {
        "cart_in_use": "hasCart"
      },
      "events": {
        "shelf_item_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "shelf_item_pickup",
          {
            "not": "cart_in_use"
          }
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying_goods",
    "text": "The shopper is prohibited from carrying shopping items by hand.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "no_more_interactions_after_return",
    "text": "Once the cart is parked in the front-left bay, the shopper is prohibited from performing any further store interaction before exiting.",
    "abstraction": {
      "state_properties": {
        "cart_parked_in_bay": "cartAt(0,1)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cart_parked_in_bay",
          "INTERACT"
        ]
      }
    }
  }
]
